#!/usr/bin/env python3
"""Пересобирает книгу живым русским языком и сохраняет связность тем."""
from pathlib import Path
import re
R=Path('.')
C=R/'book/chapters'

skill='''# Правила естественного текста книги

Этот файл — обязательная инструкция для всех будущих изменений книги.

## Как писать

- Пишите так, как объясняли бы знакомому Junior-администратору вслух.
- Один абзац — одна мысль. Обычно это 1–3 строки.
- Сначала используйте простое русское название. И только затем укажите термин из интерфейса или документации в скобках.
- Сокращение нельзя использовать раньше, чем оно расшифровано и объяснено на примере проекта.
- Команда объясняется по фактическому действию. Нельзя писать общую заготовку «читает или изменяет состояние».
- Если команда ничего не меняет, скажите это прямо.
- Пример должен относиться к MSPShield, а не к абстрактной компании.
- Не используйте искусственные англицизмы, если есть понятное русское слово.
- Не повторяйте одинаковые разделы и вопросы только ради объёма.
- Не выдавайте успешный запуск команды за доказательство результата.

## Запрещённые обороты

«Давайте погрузимся», «раскроем потенциал», «революционный подход», «трансформируйте», «разблокируйте секреты», «оптимизируйте рабочий процесс», а также безличные фразы «это сужает область поиска, но не доказывает единственную причину».

## Проверка перед публикацией

1. Поймёт ли абзац человек, который видел технологию впервые?
2. Объяснено ли каждое сокращение до первого использования?
3. Понятно ли, зачем владельцу проекта эта тема?
4. Связана ли глава с предыдущими знаниями и следующей задачей?
5. Есть ли конкретный пример из репозитория?
6. Не обещает ли текст то, что не проверено на живой инфраструктуре?
7. Можно ли сократить фразу без потери смысла?
'''
(R/'book/NATURAL_WRITING_SKILL.md').write_text(skill,encoding='utf-8')

continuity='''# Карта связности книги

Карта сделана по принципу Unlazy: сначала фиксируется полный путь обучения, затем каждая глава проверяется по входным знаниям, новым понятиям и следующему шагу.

| Этап | Что читатель уже знает | Что добавляется | К чему это ведёт |
|---|---|---|---|
| Знакомство | Общие навыки Junior | ценность, состав проекта, роли | карта доступов и Git |
| Основа | карта проекта | GitHub, Yandex Cloud, Linux и сеть | контейнеры и сервисы |
| Сервисы | сервер и сеть | Caddy, backend, MongoDB, Kaiten, почта | полный запуск |
| Эксплуатация | запущенный проект | мониторинг, MAX, журналы, backup | restore и migration |
| Деньги | технический объём | время, себестоимость, цена, загрузка | продажи и договор |
| Клиенты | цена и границы | воронка, onboarding, обслуживание | найм и рост |
| Команда | повторяемые процессы | обучение Junior и контроль | масштабирование |

При изменении главы автор проверяет обе соседние темы. Новый термин добавляется в глоссарий и объясняется в тексте до первой команды, где он нужен.
'''
(R/'book/CONTINUITY.md').write_text(continuity,encoding='utf-8')

intro='''# 0. Что это за проект и как читать книгу

MSPShield — небольшой сервис технического обслуживания компаний. На старте им занимаются два человека: владелец и продакт-менеджер. Это подработка с ограниченным временем, а не круглосуточный центр поддержки.

Клиент платит не за набор программ. Он платит за понятный порядок работы: проблемы замечают, заявки не теряются, резервные копии проверяются, изменения записываются, а ответственность сторон закреплена договором.

## Из чего состоит проект

Код и документация хранятся в GitHub. Рабочая версия запускается на виртуальной машине в Yandex Cloud. На машине работают сайт, серверная часть, база данных и мониторинг.

Заявка с сайта попадает в серверную часть. Она сохраняется в MongoDB, а затем передаётся в Kaiten и по почте. Если внешний сервис временно недоступен, заявка не должна исчезнуть.

Prometheus собирает показатели. Alertmanager решает, когда нужно предупредить владельца. Сообщения отправляются в MAX и по почте. Grafana показывает графики.

Пароли и ключи нельзя хранить в GitHub или Kaiten. Для них используется Vaultwarden. Резервные копии создаются через restic и хранятся отдельно от основной машины.

## Техническая цепочка

```text
Посетитель сайта
→ домен и HTTPS
→ Caddy
→ backend на 127.0.0.1:8001
→ MongoDB
→ очередь отправки
→ Kaiten и почта
```

Вторая цепочка следит за первой:

```text
Проверки сервисов
→ Prometheus
→ Alertmanager
→ MAX и почта
→ владелец проекта
```

Если непонятно хотя бы одно слово на схеме, это нормально. Дальше книга разбирает каждый элемент отдельно.

## Коммерческая цепочка

```text
Реклама, рекомендация, сайт, почта или площадка
→ первичный разговор
→ безопасное обследование
→ предложение и цена
→ договор и оплата
→ подключение клиента
→ регулярная работа
→ отчёт и продление
```

Kaiten нужен не только техническим специалистам. В нём видно, откуда пришла заявка, кто отвечает за следующий шаг и почему сделка остановилась.

## Как читать книгу

Идите по оглавлению, а не по номерам файлов. Номера сохранены, чтобы не сломать старые ссылки.

Незнакомое слово сначала ищите в текущем абзаце. Книга обязана объяснить его до использования. Если объяснения нет, это ошибка книги, а не читателя.

Команды выполняйте на учебной машине. Не копируйте команды изменения firewall, DNS, базы или резервных копий в рабочую среду без плана возврата.

После каждой темы отвечайте на три вопроса:

1. Что эта часть делает в MSPShield?
2. Как проверить, что она работает?
3. Что увидит клиент, если она сломается?
'''
(C/'00-что-это-за-проект.md').write_text(intro,encoding='utf-8')

chapter2='''# 2. Как спокойно разобраться в незнакомом сервере

После сбоя документация может говорить одно, а сервер — другое. В такой ситуации опасно сразу перезапускать контейнеры или менять настройки. Сначала нужно понять, что действительно запущено.

## Начинаем с версии проекта

```bash
git rev-parse HEAD
```

Команда показывает номер текущего коммита. Коммит — это сохранённая версия файлов в Git. Команда ничего не изменяет.

Скопируйте полученный номер и найдите его в GitHub. Так можно понять, совпадает ли сервер с основной веткой проекта.

Теперь проверьте незаписанные изменения:

```bash
git status --short
```

Пустой ответ означает, что Git не видит изменённых файлов. Если появились строки, не удаляйте их. Сначала выполните `git diff` и сохраните результат в журнале работ.

## Смотрим, какие сервисы описаны в Compose

```bash
docker compose config --services
```

Docker Compose читает файл `docker-compose.yml`, подставляет переменные и выводит имена сервисов. Контейнеры эта команда не запускает.

После этого посмотрите фактическое состояние:

```bash
docker compose ps
```

Здесь важны три вещи: запущен ли контейнер, какой у него статус и какие порты опубликованы на сервере.

`Up` означает только то, что процесс контейнера работает. Это ещё не доказывает, что сайт принимает заявки или что MAX доставляет сообщения.

## Проверяем открытые порты

```bash
sudo ss -lntp
```

Команда показывает программы, которые ждут сетевые подключения.

В MSPShield backend должен быть доступен на `127.0.0.1:8001`. Адрес `127.0.0.1` означает, что подключиться можно только с самой виртуальной машины. Если вы увидели `0.0.0.0:8001`, порт открыт на всех сетевых интерфейсах. Для production это ошибка.

## Проверяем ответ backend

```bash
curl -fsS http://127.0.0.1:8001/api/health
```

`curl` отправляет HTTP-запрос. Адрес указывает на backend на этой же машине.

Параметр `-f` заставляет команду завершиться ошибкой при ответе 400 или 500. `-sS` убирает индикатор загрузки, но оставляет текст ошибки.

Успешный ответ подтверждает только работу этого адреса. Он не гарантирует, что база данных, Kaiten, почта и MAX доступны.

## Смотрим журнал конкретного сервиса

```bash
docker compose logs --tail 100 backend
```

Команда показывает последние сто строк журнала backend. Она ничего не перезапускает.

Сначала найдите время ошибки. Затем прочитайте несколько строк до неё и после неё. Одна строка без контекста часто приводит к неверному выводу.

## Пример расследования

Допустим, сайт открывается, но новая заявка не появляется в Kaiten.

Не начинайте с перезапуска всего проекта. Проверьте путь заявки по частям:

1. Откройте инструменты разработчика браузера и посмотрите ответ запроса `/api`.
2. Проверьте журнал backend за то же время.
3. Убедитесь, что запись появилась в MongoDB.
4. Проверьте очередь отправки в Kaiten.
5. Только после этого проверяйте ключ Kaiten и доступность его API.

Если запись есть в базе, но нет в Kaiten, сайт и сохранение работают. Неисправность находится дальше по цепочке.

## Практика

На учебной VM запишите:

- номер коммита;
- список сервисов Compose;
- состояние контейнеров;
- порт backend;
- ответ `/api/health`;
- последние десять строк журнала backend.

Рядом с каждым пунктом напишите простыми словами, что именно он подтверждает и чего не подтверждает.
'''
(C/'02-исследование-незнакомой-системы-без-угадывания.md').write_text(chapter2,encoding='utf-8')

# Убираем шаблонный язык во всех остальных главах.
repl={
'## Модель, которую нужно построить':'## Главное',
'## Термины в рабочем смысле':'## Слова, которые встретятся дальше',
'## Что происходит внутри':'## Как это работает',
'## Разобранный пример':'## Пример',
'### Как читать пример':'### Что здесь происходит',
'## Если результат не совпал с ожиданием':'## Если что-то не работает',
'## Проверка понимания':'## Проверьте себя',
'Owner':'владелец проекта','owner':'владелец','process':'процесс','socket':'сетевое подключение',
'config path':'путь к файлу настроек','health endpoint':'адрес проверки работоспособности',
'evidence':'подтверждение','failure domain':'общая точка отказа','state':'сохранённые данные',
'interface':'точка связи','mutation':'изменение','working tree':'рабочие файлы',
'alert':'предупреждение','alerts':'предупреждения','credential':'секрет доступа',
'deploy':'развёртывание','Backup':'Резервная копия','backup':'резервная копия',
'restore':'восстановление','scope':'границы услуги','capacity':'доступное время команды',
'discovery':'первая встреча','steady state':'регулярная работа','offboarding':'завершение обслуживания'
}
for f in C.glob('*.md'):
 if f.name in {'00-что-это-за-проект.md','02-исследование-незнакомой-системы-без-угадывания.md'}: continue
 s=f.read_text(encoding='utf-8-sig')
 s=re.sub(r'^Предыдущая глава:.*\n+','',s,flags=re.M)
 for a,b in repl.items(): s=s.replace(a,b)
 s=s.replace('Это сужает область поиска, но не доказывает единственную причину | ','')
 s=re.sub(r'\n## Самостоятельная работа\n.*?(?=\n## )','\n',s,flags=re.S)
 s=re.sub(r'\n## Условие перехода\n.*\Z','\n',s,flags=re.S)
 s=s.replace('Глава завершена, если вы можете связно объяснить','После главы объясните своими словами')
 f.write_text(s,encoding='utf-8')

